 function pairDialog(){if(!gateway.enabled||!gateway.server)return;showModal('Pair this device, not a companion role.',`<p class="modal-copy">Use a short-lived one-use code from the trusted host console. Never use a model key, account password or payment credential. Origin: <b>${esc(gateway.origin)}</b></p><div class="digest">Server: ${esc(gateway.server)}</div><label>Device label<input id="device-label" maxlength="64" value="OpenBot workspace session" autocomplete="off"></label><label>One-time pairing code<input id="pair-code" type="password" minlength="43" maxlength="43" autocomplete="off" spellcheck="false"></label><p class="inline-note">Non-exportable P-256 private key, in renderer memory only. Reload needs a fresh pairing grant. No hardware-keystore claim.</p><p class="form-error" id="pair-error"></p><button class="button primary full" id="pair-submit">Pair device</button>`,'pair');}
 function newQADialog(){if(!gateway.can('propose'))return;if(pendingProposal){showModal('Read back the previous proposal first.',`<p class="modal-copy">A prior proposal outcome was uncertain. Do not automatically resend it or reuse its request ID with changed content. Refresh the server, inspect task records, then explicitly decide whether to create a new proposal.</p><div class="digest">Request ID: ${esc(pendingProposal.request_id)}</div><div class="actions"><button class="button" id="inspect-prior-proposal">Refresh & inspect</button><button class="button" id="ack-new-proposal">I inspected the outcome; start a new proposal</button></div>`);return;}showModal('Propose fixed owned-QA work.',`<p class="modal-copy">This creates a server proposal, not approval. Actor, venture, scope, catalog and budget authority come from the trusted server—not the selected companion name.</p><label>Bundled first-party sample<select id="fixture">${window.OpenBotGateway.fixtures.map(v=>`<option>${v}</option>`).join('')}</select></label><label>Goal<input id="goal" maxlength="512" value="Validate the owned invoice sample"></label><label>Acceptance criteria<textarea id="acceptance" maxlength="512">Run independent assertions and documentation examples; report evidence for every finding.</textarea></label><label class="check-row"><input id="rights" type="checkbox"><span>I have testing rights for this first-party sample and approve this bounded AI-assisted QA/documentation method.</span></label><div class="digest">Destination: local-review · maximum provider exposure: USD 0.00<br>No customer program, external delivery, custom shell or provider call.</div><p class="form-error" id="proposal-error"></p><button class="button primary full" id="propose-submit">Create server proposal</button>`);}
